function dir$m71(p){
  this.constructor(p);
}
dir$m71.prototype = new DirEvent();
dir$m71.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid();
  var exp = {
    t_so_luong: ['@t_so_luong', '[so_luong]']
  }
  p.applyExpression(exp, g, false); //Ko can de quy tinh cong thuc

  g.FomulaApplied = {
    "so_luong":["t_so_luong"]
  } //Gan lai valid của từng cột sẽ tính các công thức nào theo thứ tự.

  //console.log(JSON.stringify(g.FomulaApplied)); //Gan la ds cong thuc tinh cho cot nao do: 

  dir$m71DisabledMasterField(p, g);
  dir$m71DisabledStatusByAction(p);
}

dir$m71.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
      var rows = dt.findRow("[so_luong] > [sl_ton]") //Ban chuan chi xu ly canh bao ton kho tuc thoi tren client
      if (p.valForm('status') != '0' && p.options.dataChanged && rows.length) {
        $.question('$VoucherCurrentStockOverload', $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v)
            p.options.event.buttonDialogClick(id, false);
          else {
            p.tabActive("1");
            p.jCell(rows[0], 'so_luong', 0).focus();
          }
        });
        return false;
      }
      break;
    default:
      break;
  }
  return true;
}

dir$m71.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c){
    case 'ma_vt':
      p.grequest(g, 'Item', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run) {
        p.calcValidExpression(g, 'he_so', r);
        dir$m71DisabledMasterField(p, g);
      }, r);
      break;
    case 'dvt':
      p.grequest(g, 'UOM', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run) {
        p.calcValidExpression(g, 'he_so', r);
      }, r);
      break;
    case 'ma_kho':
      p.grequest(g, 'Site', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run){
        //Xu ly sau khi valid ma_kho
      }, r);
      break;
    case 'ma_lo':
      if (p.options._lot_current_stock) p.grequest(g, 'Lot', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], null, r);
      break;
    case 'ma_vi_tri':
      if (p.options._location_current_stock) p.grequest(g, 'Location', '', ['ma_vt', 'dvt', 'he_so', 'ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], null, r);
      break;
    default:
      break;
  }
}
dir$m71.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      break;
    default:
      break;
  }
}

dir$m71.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$m71DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$m71DisabledMasterField(p, g){
  var dt = g.data, rows = dt.findRow("[ma_vt].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('unit_id', dis);
  p.setInactive('unit_id', true);
  rows = dt.findRow("[ma_vt].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('ma_bp', dis);
}
function dir$m71DisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}







